exercises.tests:
def test_username_is_str():
    assert isinstance(username, str), "username должен быть строкой"


def test_age_is_int():
    assert isinstance(age, int) and not isinstance(age, bool), "age должен быть целым числом (int)"


def test_email_is_str_with_at():
    assert isinstance(email, str) and "@" in email, "email должен быть строкой, содержащей символ @"


def test_is_admin_is_bool():
    assert isinstance(is_admin, bool), "is_admin должен быть True или False"


def test_balance_is_number():
    assert isinstance(balance, (int, float)) and not isinstance(balance, bool), "balance должен быть числом"

def test_original_mutated_via_alias():
    assert original == [1, 2, 3, 4], "alias.append(4) должен был изменить original тоже — это одна и та же ссылка"


def test_same_object_is_true():
    assert same_object is True, "original и alias — одна и та же ссылка, same_object должен быть True"


def test_same_object_uses_id():
    assert same_object == (id(original) == id(alias)), "same_object должен быть результатом сравнения id(original) и id(alias)"

def test_cascade_values():
    assert attempt_1 == 0 and attempt_2 == 0 and attempt_3 == 0, "attempt_1, attempt_2, attempt_3 должны быть равны 0"


def test_cascade_is_same_reference():
    assert attempt_1 is attempt_2 is attempt_3, "переменные должны ссылаться на один и тот же объект — используй каскадное присваивание attempt_1 = attempt_2 = attempt_3 = 0"


def test_all_same_object_flag():
    assert all_same_object is True, "all_same_object должен быть True — все три переменные это одна и та же ссылка"

def test_immutable_int_not_affected():
    assert x_after == 10, "x — int, неизменяемый тип: присваивание y = x, а затем изменение y, не должно повлиять на x"


def test_mutable_list_shared_reference():
    assert list_a_after == [1, 2, 99], "list_a и list_b — одна и та же ссылка на изменяемый список, изменение через list_b видно и в list_a"
